 @Override protected void onActivityResult(int q,int r,Intent d){super.onActivityResult(q,r,d);if(r!=RESULT_OK||d==null)return;if(q==PICK){zip=d.getData();fileLabel.setText("ZIP: "+zip.getLastPathSegment());}if(q==SAVE&&apk!=null){try(OutputStream o=getContentResolver().openOutputStream(d.getData())){o.write(apk);say("APK guardado: "+apkName);}catch(Exception e){say("Error guardando APK: "+e.getMessage());}}}
 String crypt(String s)throws Exception{KeyStore k=KeyStore.getInstance("AndroidKeyStore");k.load(null);SecretKey key;if(!k.containsAlias("alex_token")){KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder("alex_token",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());key=g.generateKey();}else key=(SecretKey)k.getKey("alex_token",null);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key);byte[] v=c.doFinal(s.getBytes("UTF-8")),iv=c.getIV(),all=new byte[iv.length+v.length];System.arraycopy(iv,0,all,0,iv.length);System.arraycopy(v,0,all,iv.length,v.length);return Base64.encodeToString(all,Base64.NO_WRAP);}
 String uncrypt(String s)throws Exception{byte[] a=Base64.decode(s,Base64.NO_WRAP),iv=new byte[12],v=new byte[a.length-12];System.arraycopy(a,0,iv,0,12);System.arraycopy(a,12,v,0,v.length);KeyStore k=KeyStore.getInstance("AndroidKeyStore");k.load(null);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,(SecretKey)k.getKey("alex_token",null),new GCMParameterSpec(128,iv));return new String(c.doFinal(v),"UTF-8");}
 void save(){try{String x=token.getText().toString().trim();if(!x.isEmpty())getPreferences(0).edit().putString("secret",crypt(x)).apply();getPreferences(0).edit().putString("owner",owner.getText().toString().trim()).putString("repo",repo.getText().toString().trim()).apply();token.setText("");token.setHint("Token guardado cifrado en Android Keystore");say("Configuración guardada de forma cifrada.");}catch(Exception e){say("No se pudo guardar: "+e.getMessage());}}
 void load(){owner.setText(getPreferences(0).getString("owner",""));repo.setText(getPreferences(0).getString("repo",""));if(!getPreferences(0).getString("secret","").isEmpty())token.setHint("Token guardado cifrado; pega uno nuevo para reemplazarlo");}
 String secret()throws Exception{String s=getPreferences(0).getString("secret","");if(s.isEmpty())throw new Exception("Introduce y guarda un token de GitHub.");return uncrypt(s);}
 JSONObject request(String method,String url,String body,String key)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setRequestMethod(method);c.setConnectTimeout(20000);c.setReadTimeout(30000);c.setRequestProperty("Accept","application/vnd.github+json");c.setRequestProperty("X-GitHub-Api-Version","2022-11-28");c.setRequestProperty("Authorization","Bearer "+key);c.setRequestProperty("User-Agent","AlexAPKBuilder");if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream o=c.getOutputStream()){o.write(body.getBytes("UTF-8"));}}int n=c.getResponseCode();InputStream in=n>=200&&n<300?c.getInputStream():c.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();if(in!=null){byte[] b=new byte[8192];int z;while((z=in.read(b))>0)out.write(b,0,z);}String s=out.toString("UTF-8");c.disconnect();if(n<200||n>=300)throw new Exception("GitHub HTTP "+n+": "+s);return s.isEmpty()?new JSONObject():new JSONObject(s);}
 byte[] workflowBytes()throws Exception{InputStream in=getAssets().open("cloud-build.yml");ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))>0)o.write(b,0,n);in.close();return o.toByteArray();}
 void put(String base,String path,byte[] bytes,String msg,String key)throws Exception{JSONObject old=null;try{old=request("GET",base+"/contents/"+path,null,key);}catch(Exception ignored){}JSONObject b=new JSONObject();b.put("message",msg);b.put("content",Base64.encodeToString(bytes,Base64.NO_WRAP));if(old!=null&&old.has("sha"))b.put("sha",old.getString("sha"));request("PUT",base+"/contents/"+path,b.toString(),key);}
 void build(){if(zip==null){say("Selecciona un ZIP primero.");return;}save();final Uri selectedZip=zip;final String targetOwner=owner.getText().toString().trim(),targetRepo=repo.getText().toString().trim();final String type=mode.getSelectedItemPosition()==0?"debug":"release";worker.execute(()->{try{String key=secret(),o=targetOwner,r=targetRepo;if(o.isEmpty()||r.isEmpty())throw new Exception("Completa propietario y repositorio.");String base="https://api.github.com/repos/"+o+"/"+r;say("Verificando que el repositorio sea privado…");if(!request("GET",base,null,key).optBoolean("private",false))throw new Exception("El repositorio debe ser PRIVADO. No se enviará código a un repositorio público.");
 byte[] data;try(InputStream in=getContentResolver().openInputStream(selectedZip);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))>0){out.write(b,0,n);if(out.size()>20*1024*1024)throw new Exception("ZIP mayor a 20 MB: límite de esta versión.");}data=out.toByteArray();}
 say("Instalando workflow seguro…");put(base,".github/workflows/cloud-build.yml",workflowBytes(),"Install Alex APK cloud workflow",key);say("Subiendo proyecto al repositorio privado…");put(base,"incoming/project.zip",data,"Upload temporary project ZIP",key);
 JSONObject d=new JSONObject();d.put("ref","main");JSONObject inputs=new JSONObject();inputs.put("build_type",type);d.put("inputs",inputs);HttpURLConnection c=(HttpURLConnection)new URL(base+"/actions/workflows/cloud-build.yml/dispatches").openConnection();c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Authorization","Bearer "+key);c.setRequestProperty("Accept","application/vnd.github+json");c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(d.toString().getBytes("UTF-8"));}int code=c.getResponseCode();c.disconnect();if(code!=204)throw new Exception("No se pudo iniciar Actions (HTTP "+code+"). Revisa permiso Actions Read and write.");
 long start=System.currentTimeMillis();JSONObject run=null;String runId="";for(int i=0;i<90;i++){Thread.sleep(8000);JSONObject list=request("GET",base+"/actions/runs?event=workflow_dispatch&per_page=10",null,key);JSONArray a=list.optJSONArray("workflow_runs");if(a!=null)for(int j=0;j<a.length();j++){JSONObject x=a.getJSONObject(j);String created=x.optString("created_at","");String since=new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss'Z'",java.util.Locale.US).format(new java.util.Date(start-90000));if(created.compareTo(since)>=0&&x.optString("path").endsWith("cloud-build.yml")){run=x;runId=x.optString("id");break;}}if(run!=null&&"completed".equals(run.optString("status")))break;say("Compilando en GitHub Actions… "+(run==null?"iniciando":run.optString("status")));}if(run==null)throw new Exception("No se encontró la ejecución. Revisa GitHub Actions.");if(!"success".equals(run.optString("conclusion")))throw new Exception("La compilación falló: "+run.optString("conclusion")+". Consulta los logs en GitHub.");
 say("Compilación correcta. Descargando artefacto…");JSONObject arts=request("GET",base+"/actions/runs/"+runId+"/artifacts",null,key);JSONArray aa=arts.optJSONArray("artifacts");String url=null;if(aa!=null)for(int i=0;i<aa.length();i++){JSONObject a=aa.getJSONObject(i);if(a.optString("name").startsWith("alex-apk-")){url=a.optString("archive_download_url");break;}}if(url==null)throw new Exception("No se encontró el artefacto APK.");HttpURLConnection ac=(HttpURLConnection)new URL(url).openConnection();ac.setRequestProperty("Authorization","Bearer "+key);ac.setInstanceFollowRedirects(false);ac.getResponseCode();String location=ac.getHeaderField("Location");ac.disconnect();if(location==null)throw new Exception("No se recibió URL temporal de descarga.");ByteArrayOutputStream zipped=new ByteArrayOutputStream();try(InputStream in=new URL(location).openStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)zipped.write(b,0,n);}try(ZipInputStream z=new ZipInputStream(new ByteArrayInputStream(zipped.toByteArray()))){ZipEntry e;apk=null;while((e=z.getNextEntry())!=null){if(!e.isDirectory()&&e.getName().endsWith(".apk")){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=z.read(b))>0)out.write(b,0,n);apk=out.toByteArray();apkName=e.getName().substring(e.getName().lastIndexOf('/')+1);break;}}}if(apk==null)throw new Exception("El artefacto no contiene APK; revisa que el ZIP sea un proyecto Android Gradle.");say("¡APK listo! "+(apk.length/1024)+" KB. Pulsa GUARDAR APK EN EL TELÉFONO.");}catch(Exception e){say("Error: "+e.getMessage());}});}
 void saveApk(){if(apk==null){say("Todavía no hay APK descargado.");return;}Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/vnd.android.package-archive");i.putExtra(Intent.EXTRA_TITLE,apkName);startActivityForResult(i,SAVE);}
